import hashlib
import hmac

def verify_webhook_signature(raw_utf8, signature, secret):
    expected = hmac.new(secret, raw_utf8, hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

def verify_password(password, stored):
    return hash_password(password) == stored

